public static str attachBase64ToCommon(Common _common, str _base64, str _fileExtension, str _note = "@TFM:CreatedfromMobileWMS")
{
    str fileName = TFMHelper::descriptionFromCommon(_common) + '.';
    DocuRef     resultDocuRef;
    /*System.Drawing.Image img = System.Drawing.Image::FromStream( new System.IO.MemoryStream(System.Convert::FromBase64String(_base64)));
    System.IO.MemoryStream ms = new System.IO.MemoryStream();
    img.Save(ms,System.Drawing.Imaging.ImageFormat::Png);*/

    if(strScan(_base64,'.jpg;',1,strLen(_base64)))
    {
        TFMMediaQueue::AddMap2Queue(_common, TFMMediaQueue::separateIDsAndComments(_base64), '*');
        return "@TFM:fileAttached";
    }

    #ifnot.isAX6
    resultDocuRef = DocumentManagement::attachFileToCommon(_common, TFMParameters::find().DocuTypeId,new System.IO.MemoryStream(System.Convert::FromBase64String(_base64)), filename + _fileExtension, _fileExtension, filename + _fileExtension,_note);
    #endif
    #if.isAX6
    [docuRefRecId] = DocumentFileHelper::attachDocumentAsUser(['', _base64, filename + _fileExtension, '', DateTimeUtil::utcNow(), _common.TableId, _common.RecId, _common.dataAreaId, TFMParameters::find().DocuTypeId]);
    ttsBegin;
    select forUpdate resultDocuRef where resultDocuRef.RecId == DocuRefRecId;
    resultDocuRef.Notes = _note;
    resultDocuRef.update();
    ttsCommit;
    #endif

    if(_common.tableId == tableNum(InventTable))
    {
        EcoResProductImage::create(resultDocuRef);
    }

    return "@TFM:fileAttached";
}

public static str matchRegex(str _text, str _pattern)
{
    System.Text.RegularExpressions.Regex regex;
    System.Text.RegularExpressions.MatchCollection matches;
    System.Text.RegularExpressions.Match match;
    int i;
    str foundStr;

    regex = new System.Text.RegularExpressions.Regex(_pattern);
    matches = regex.Matches(_text);

    for (i = 0; i < matches.get_Count(); i++)
    {
        match = matches.get_Item(i);

        foundStr = match.get_Groups().get_Item(1).get_Value();
        if (!foundStr)
        {
            foundStr = match.Value;
        }

    }
    return foundStr;
}

public static Set matchRegexSet(str _text, str _pattern)
{
    System.Text.RegularExpressions.Regex regex;
    System.Text.RegularExpressions.MatchCollection matches;
    System.Text.RegularExpressions.Match match;
    int i;
    Set foundStr = new Set(Types::String);
    str matchedStr;

    regex = new System.Text.RegularExpressions.Regex(_pattern);
    matches = regex.Matches(_text);

    for (i = 0; i < matches.get_Count(); i++)
    {
        match = matches.get_Item(i);

        matchedStr = match.get_Groups().get_Item(1).get_Value();
        if (!matchedStr)
        {
            foundStr.add(match.Value);
        }
        else
        {
            foundStr.add(matchedStr);
        }

    }
    return foundStr;
}

public static Map getParametersFromClassAndMethod(ClassName _clsName, MethodName _methodName)
{
    SysDictClass    sdc = new SysDictClass(className2Id(_clsName));
    SetEnumerator   methodsOnClass = sdc.methods(true,false,true).getEnumerator();
    SysDictMethod   sdm;
    int             idx;
    Map             retMap = new Map(Types::String, Types::String);
    while (methodsOnClass.moveNext())
    {
        sdm = methodsOnClass.current();
        for (idx = 1; idx <= sdm.parameterCnt() && _methodName == sdm.name(); idx++)
        {
            retMap.insert(sdm.parameterName(idx),sdm.parameterTypeName(idx) ? sdm.parameterTypeName(idx) : strFmt('%1',sdm.parameterType(idx)));
        }
    }
    return retMap;
}

public static Common backendId2Record(str _backendId)
{
    container backendCon = strSplit(_backendId,'/').pack();
    Common		record;
    Query                   q = new Query();
    QueryRun                qr;
    QueryBuildDataSource    qbds = q.addDataSource(tablename2id(conPeek(backendCon,4)));


    qbds.addRange(fieldName2Id(tablename2id(conPeek(backendCon,4)),conPeek(backendCon,5))).value(strFmt('%1',conPeek(backendCon,6)));

    qr = new QueryRun(q);

    while (qr.next())
    {
        record = qr.get(tableName2id(conPeek(backendCon,4)));

        break;
    }

    return record;
}

public static str splitTextToMultilines(str _line)
{
    str line1 = _line;
    str line2 = '';
    int line1Length = strLen(line1);
    int indexOfLastUppercase;

    if(line1Length > 17)
    {
        indexOfLastUppercase = TFMHelper::findIndexOfFirstCapitalLetterFromMiddle(line1);
        if(indexOfLastUppercase > 0)
        {
            line2 = subStr(line1, indexOfLastUppercase, (line1Length + 1) - indexOfLastUppercase);
            line1 = subStr(line1, 0, indexOfLastUppercase - 1) + '-';
        }
    }
    return line1 + TFMConstants::lineBreak() + line2;
}

public static int findIndexOfFirstCapitalLetterFromMiddle(str _text)
{
    int i;
    int stringLength = strLen(_text);
    str character;

    for (i=stringLength/2; i<=stringLength; i+=1)
    {
        character = subStr(_text, i, 1);

        //If the character is NOT EQUAL to it's lowercase counterpart, it must be uppercase:
        if (char2num(_text, i) != char2num(strLwr(_text), i))
        {
            return i;
        }
    }
    return -1;
}

public static TFMBackendId generateBackendId(Common _common, TFMOrderTypes _orderType = '')
{
    SysDictTable	sdc = new SysDictTable(_common.tableId);
    TFMBackendId	backendId = tableId2Name(_common.TableId) + '/' + fieldId2Name(_common.tableId, sdc.primaryKeyField()) + '/' + strFmt('%1', _common.(sdc.primaryKeyField())) + (_orderType ? '/' + _orderType : '');
    return backendId;
}

    public static Common BackendId2Buffer(TFMBackendId _backendId)
    {
        container		backendCon = TFMHelper::strSplit(_backendId,'/').pack();
		SysDictTable	sdc		= new SysDictTable(tableName2Id(conPeek(backendCon,4)));
        Common			common = sdc.makeRecord();
        TableId			tableId= common.tableId;
        FieldId			fieldId = fieldName2Id(tableId,conPeek(backendCon,5));
        Query                   q = new Query();
        QueryRun                qr;
        QueryBuildDataSource    qbds = q.addDataSource(tableId);
        qbds.addRange(fieldId).value(strFmt('%1',conPeek(backendCon,6)));
        qr = new QueryRun(q);
        qr.next();
        common = qr.get(tableId);

        return common;
    }

public static str BackendId2UniqueID(TFMBackendId _backendId)
{
    container		backendCon = TFMHelper::strSplit(_backendId,'/').pack();
    return conPeek(backendCon,6);        
}

    public static void addValueMapToParmMethod(Map _values, Object _class)
    {
        MapEnumerator		mEnum = _values.getEnumerator();
        ClassId             classClassId = classIdGet(_class);
        SysDictClass        dC = new SysDictClass(classClassId);
        Set                 parmMethods = TFMFormLookupHelper::parmMethodsOnClass(classClassId);

		while (mEnum.moveNext())
        {
            TFMHelper::addValueToParmMethod(mEnum.currentKey(),_class,mEnum.currentValue(),dC,parmMethods);
        }
    }

public static anytype addValueToParmMethod(str _key, Object _class, str _value, SysDictClass _dC = null, Set _parmMethods = null ) 
{
    anytype                 convertedValue;
    SysDictMethod           sdm;
    SysDictClass            dC = _dC != null ? _dC : new SysDictClass(classIdGet(_class));
    SysDictEnum             sde;
    Set                     parmMethods = _parmMethods != null ? _parmMethods : TFMFormLookupHelper::parmMethodsOnClass(dC.id());        
    Types                   baseType;
    TFMParameterAttribute   parmAttrib;

    if (parmMethods.in('parm'+ _key))
    {
        sdm = new SysDictMethod(UtilElementType::ClassInstanceMethod,dC.id(),'parm'+ _key);

        baseType = sdm.returnType();
        if (baseType == Types::UserType && sdm.returnTypeName())
        {
            baseType = new DictType(extendedTypeName2Id(sdm.returnTypeName())).baseType();
        }
        if (baseType == Types::Class)
        {
            return null;
        }
        convertedValue = TFMDocCustomFunctionFlow::ConvertToType(_value, baseType,baseType != Types::Enum ? extendedTypeId2name(sdm.returnId()) : sdm.returnTypeName());

        if(baseType == Types::Enum && convertedValue == 255)
        {
            parmAttrib = sdm.getAttribute(classStr(TFMParameterAttribute));
            if(parmAttrib.parmDefaultValue() != null)
            {
                convertedValue = parmAttrib.parmDefaultValue();
            }
            else
            {
                sde = new SysDictEnum(new DictType(extendedTypeName2Id(sdm.ReturnTypeName())).enumId());

                convertedValue = sde.firstValue();
            }
        }

        return dC.callObject('parm' + _key,_class,convertedValue);
    }
    return null;
}

public static str convertCamelCaseToNiceText(str _missingSpaces)
{
    int totalLength = strLen(_missingSpaces);
    str result, curChar, prevChar, nextChar;
    int i;

    if(totalLength)
    {
        curChar = subStr(_missingSpaces, 1, 1);
        result = strUpr(curChar);
    }

    for (i = 2; i <=totalLength; i++)
    {
        prevChar = curChar;
        curChar = nextChar ? nextChar : subStr(_missingSpaces,i,1);
        nextChar = subStr(_missingSpaces, i+1, 1);

        // Add space before character?
        result += ( (   char2Num(curChar,1) > 64 &&     // current is UPPER case
                        char2Num(curChar,1) < 91 ) &&   // and either
                    ( ( char2Num(prevChar,1) > 96 &&    // previous is lower case
                        char2Num(prevChar,1) < 123 ) || // or 
                      ( char2Num(nextChar,1) > 96 &&    // next is lower case
                        char2Num(nextChar,1) < 123 ) )  
                    ? ' ' : '') + curChar;
    }
    return result;
}

public static str capitalLetterSentence(str _sentence)
{
    ListEnumerator lEnum = TFMHelper::strSplit(_sentence,' ').getEnumerator();
    str             result;
    while (lEnum.moveNext())
    {
        result += (result ? ' ' : '') + strUpr(subStr(lEnum.current(),1,1)) + strLwr(subStr(lEnum.current(),2,strLen(lEnum.current())));
    }
    return result;
}

/// <summary>
/// Removes the parm form the string if it starts with parm. 
/// </summary>
/// <param name = "_input"></param>
/// <returns></returns>
public static str removeParmFromStr(str _input)
{
    if(_input && strLen(_input) > 4)
    {
        if(subStr(_input,1,4) == 'parm')
        {
            return subStr(_input,5,strLen(_input));
        }
    }
    return _input;
}

