public static str descriptionFromCommon(Common _common)
{
    Description255  ret = new DictTable(_common.TableID).label();
    MapEnumerator   keyFields = TFMHelper::getPrimaryKeysFromTableName(tableId2Name(_common.TableID)).getEnumerator();
    DictField       dictField;

    while (keyFields.moveNext())
    {
        dictField = keyFields.currentValue();
        ret += ', ' + dictField.label() + ' ' + strFmt('%1',_common.(dictField.id()));
    }

    return ret;
}

public static Common getBuffer(TableName _tableName, Object _class)
{
    DictClass                       DC = new DictClass(classIdGet(_class));
    TFMOrderPostDataSetAttribute    attr;
    Array                           array;
    int                             i, j;
    DictMethod                      DM;

    for (i = 1; i <= DC.objectMethodCnt(); i++)
    {
        DM = DC.objectMethodObject(i);
        array = DM.getAttributes(classStr(TFMOrderPostDataSetAttribute));
        if (array != null)
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                attr = array.value(j);
                if (attr.name() == _tableName || !_tableName)
                {
                    return DC.callObject(DM.name(),_class);
                }
            }
        }
    }
    return null;
}

