public static Set xmlLines2Set(XmlElement _orderElement)
{
    Set         lines = new Set(Types::Class);
    Map         line = new Map(Types::String, Types::String);
    XmlNodeList lineNodeList = _orderElement.getElementsByTagName( 'Line' );
    XMLNode     lineNode, registrationNode, subNode;
    XMLNodeList lineNodeRegistrationList;
    int         i, n;
    for (i = 0; i < lineNodeList.length(); i++) // Save the registration data into table
    {
        lineNode = lineNodeList.item(i);
        lineNodeRegistrationList = lineNode.childNodes();

        for (n = 0;n < lineNodeRegistrationList.length(); n++)
        {
            line = new Map(Types::String, Types::String);
            registrationNode = lineNodeRegistrationList.item(n);
            subNode = registrationNode.firstChild();
            while (subNode)
            {
                line.insert(subNode.name(), subNode.innerText());
                subNode = subNode.nextSibling();
            }
            line.insert(TFMConstants::AttributeLineNumber(),lineNode.attributes().getNamedItem(TFMConstants::AttributeLineNumber()).text());
            Lines.add(line);
        }
    }

    return lines;
}

public static real floatParse(str _numberString)
{
    str textNumber = _numberString;
    if (!_numberString)
    {
        return 0;
    }
    if (!strScan(_numberString,'.',1,1000) && !strScan(_numberString,',',1,1000))
    {
        textNumber += '.0';
    }
    else if(substr(_numberString,1,1) == '.' || subStr(_numberString,1,1) == ',')
    {
        textNumber = '0' + textNumber; // NumberFormat for 'de-DE' seems to throw error on leading decimal separator
    }
    #if.isAX6
    System.Globalization.CultureInfo invariant = System.Globalization.CultureInfo::get_InvariantCulture();
    System.Globalization.CultureInfo deCult = System.Globalization.CultureInfo::GetCultureInfo('de-DE');
    System.Double float1 = System.Double::Parse(textNumber, invariant.get_NumberFormat());
    System.Double float2 = System.Double::Parse(textNumber, deCult.get_NumberFormat());

    System.Double scalar = subStr(textNumber,1,1) == '-' ? -1 : 1;
    System.Double midresult = System.Math::Min(System.Math::Abs(float1), System.Math::Abs(float2));
    real res = midResult;
    real rScalar = scalar;
    return res * rscalar;
    #endif
    #ifnot.isAx6
    System.Double float1 = System.Double::Parse(textNumber, System.Globalization.CultureInfo::InvariantCulture.NumberFormat);
    System.Double float2 = System.Double::Parse(textNumber, System.Globalization.CultureInfo::GetCultureInfo('de-DE').NumberFormat);
    return System.Math::Min(System.Math::Abs(float1), System.Math::Abs(float2)) * (float1 < 0 ? -1 : 1);
    #endif
}

/// <summary>
/// Finds out if there is a class that has a certain attribute. Please notice this method does only support finding classes where there is only one attribute defined. 
/// 
/// NB!: Use TFMGetRegistrationConfiguration::getClassFromSysAttribute instead.
/// </summary>
/// <param name = "_baseClassName"></param>
/// <param name = "_sysAttribute"></param>
/// <returns></returns>
public static Object getClassFromSysAttribute(ClassName       _baseClassName, SysAttribute    _sysAttribute)
{
    SysDictClass        dc = new SysDictClass(className2Id(_baseClassName));
    ListEnumerator      classesExtending = dc.extendedBy().getEnumerator();
    SysDictClass        dcSub;
    ClassId             attributeClassId = classIdGet(_sysAttribute);
    SysDictClass        attrDC = new SysDictClass(classIdGet(_sysAttribute));
    boolean             thereIsAMatch;
    Object              result = dc.isAbstract() ? null : dc.makeObject();
    Object              testResult;
    MethodName          methodname;
    Set                 parmMethodsOnAttributeClass  = TFMFormLookupHelper::parmMethodsOnClass(attributeClassId);
    SetEnumerator       sEnum;
    ExecutePermission   exePerm;
    ClassName attributeClassName = classId2Name(attributeClassId);

    while (classesExtending.moveNext())
    {
        dcSub = new SysDictClass(classesExtending.current());

        testResult = dcSub.getAttribute(attributeClassName);
        if (testResult == null)
        {
            continue;
        }

        thereIsAMatch = true;
        exePerm = new ExecutePermission();
        exePerm.assert();
        sEnum = parmMethodsOnAttributeClass.getEnumerator();
        while (sEnum.moveNext())
        {
            methodname = sEnum.current();
            thereIsAMatch = thereIsAMatch && (attrDC.callObject(methodname,testResult) == attrDC.callObject(methodname,_sysAttribute));
        }
        if (thereIsAMatch)
        {
            return dcSub.makeObject();
        }
        CodeAccessPermission::revertAssert();
    }

    return result;
}

public static Map getPrimaryKeysFromTableName(TableName _tableName)
{
    Map             retMap = new Map(Types::String, Types::Class);
    int             i;
    DictField       dictField;
    DictTable       dictTable = new SysDictTable(tablename2id(_tableName));
    DictIndex       dictIndex = dictTable ? new DictIndex(tablename2id(_tableName),dictTable.clusterIndex()) : null;
    if (!DictIndex)
    {
        return retMap;
    }

    for (i = 1; i <= DictIndex.numberOfFields();i++)
    {
        dictField = new DictField(DictTable.id(), dictIndex.field(i));
        retMap.insert(dictField.name(),dictField);

    }
    return retMap;
}

    public static Map fieldsOnTable(TableName _tableName)
    {
        Map         returnMap   = new Map(Types::String, Types::Int64);
        DictTable   dt          = new DictTable(tableName2Id(_tableName));
		int         fieldNo     = 0;

		if (dt == null)
        {
            return returnMap;
        }

        for (fieldNo = 0; fieldNo <= dt.fieldCnt(); fieldNo++)
        {
            if (!(new DictField(tableName2Id(_tableName),dt.fieldCnt2Id(fieldNo)).isSystem()))
            {
                returnMap.insert(dt.fieldName(dt.fieldCnt2Id(fieldNo)),dt.fieldCnt2Id(fieldNo));
            }
        }
        return returnMap;
    }

public static Set getBuffers(Map _values, str _tableName, Map _replacementMap = new Map(Types::String, Types::Class))
{
    str             refRecord   = _values.exists(tableStr(ReferenceIdentity)) ? _values.lookup(tableStr(ReferenceIdentity)) : '';
    Common          record = TFMHelper::getBufferFromStr(refRecord);

    Set             records = new Set (Types::Record);
    QueryRun        qr;
    if (record != null && tableId2Name(record.TableId) == _tableName)
    {
        records.add(record);
        return records;
    }

    if (!record)
    {
        qr = TFMHelper::findBuffersFromMap(_values,_tableName, _replacementMap);
    }
    else
    {
        qr = TFMGenericDataHelper::getRelatedTable(record, _tableName);
    }
    while (qr.next())
    {
        record = qr.get(tableName2id(_tableName));
        records.add(record);
    }

    return records;
}

    public static Map mergeMaps(Map _map1, Map _map2, boolean _appendValue = false, str _appendStr = TFMConstants::lineBreak())
    {
        Map retMap;
        MapEnumerator mapEnum;
        str existingValue;

        if( !_map1)
        {
            //throw error(Error::wrongUseOfFunction(funcName()));
            _map1 = new Map(_map2.keyType(),_map2.valueType());
		}
        // Check compatibility
        if(_map1 && _map2)
        {
            if(_map1.keyType() != _map2.keyType() || _map1.valueType() != _map2.valueType())
            {
                throw error(Error::wrongUseOfFunction(funcName()));
            }
        }

        retMap = _map1;
        mapEnum = _map2.getEnumerator();
        while(mapEnum.moveNext())
        {
            if( !retMap.exists(mapEnum.currentKey()))
            {
                retMap.insert(mapEnum.currentKey(), mapEnum.currentValue());
            }
            else if (_appendValue && _map1.valueType() == Types::String)
            {
                existingValue = retMap.lookup(mapEnum.currentKey());
                retMap.insert(mapEnum.currentKey(),  mapEnum.currentValue()+ (existingValue ? _appendStr : '')+existingValue);
            }
        }
        return retMap;
    }

public static QueryRun findBuffersFromMap(Map _values, str _tableName, Map _replacementMap = new Map(Types::String, Types::Class))
{        
    Map                     primaryKeys = TFMHelper::getPrimaryKeysFromTableName(_tableName);
    MapEnumerator           mEnum       = _replacementMap.elements() ? _replacementMap.getEnumerator() : primaryKeys.getEnumerator();
    DictField               dictField;
    Query                   q = new Query();
    QueryRun                qr;
    QueryBuildDataSource    qbds = q.addDataSource(tablename2id(_tableName));
    QueryBuildRange         qbr;

    while (mEnum.moveNext())
    {
        dictField = mEnum.currentValue();
        qbr = qbds.addRange(fieldName2id(tablename2id(_tableName),dictField.name()));
        qbr.value(_values.exists(mEnum.currentKey()) ? _values.lookup(mEnum.currentKey()) : '');
    }

    qr = new QueryRun(q);

    return qr;
}

public static Common getBufferFromStr(str _refRecordStr)
{
    container   refCon;
    Common      record;
    refrecid    refID;

    if (!_refRecordStr)
    {
        return null;
    }
    refCon      = strSplit(_refRecordStr,';').pack();
    record          = new DictTable(tableName2Id(conPeek(refCon ,4))).makeRecord();
    refID           = str2Int64(conPeek(refCon ,5));
    select firstonly record where record.RecId == refID;

    return record;
}

public static TFMInputTypes baseType2InputType(Types _type)
{
    TFMInputTypes ret = TFMInputTypes::Text;
    switch ( _type)
    {
        case Types::Int64 :
        case Types::String :
            ret = TFMInputTypes::Text;//#InputTypeText;
            break;
        case Types::Date : 
            ret = TFMInputTypes::Date;//#InputTypeDate;
            break;
        case Types::Integer :
            ret = TFMInputTypes::Integer;//#InputTypeInteger;
            break;
        case Types::Enum : 
            ret = TFMInputTypes::List;//#InputTypeList;
            break;

        case Types::Real :
            ret = TFMInputTypes::Decimal;//#InputTypeDecimal;
            break;
    }

    return ret;
}

public static str strFmt(str _inStr, container _values)
{
    //to avoid BPUnusedStrFmtArgument 
    str outStr = _inStr;
    int conCount = 1;

    for (conCount = 1; conCount <= conLen(_values); conCount++)
    {
        outStr = strReplace(outStr,'%'+int2Str(conCount),strFmt('%1',conPeek(_values,conCount)));
    }
    return outStr;
}

static List strSplit(str _stringToSplit, str _delimiter)
{
    List list = new List(Types::String);
    int oldPos = 1;
    int pos;
    int delLength = strLen(_delimiter);
    int strLength = strLen(_stringToSplit);

    do
    {
        pos = strScan(_stringToSplit, _delimiter, oldPos, strLength);
        if (!pos)
        {
            pos = strLength+1;
        }
        list.addEnd(subStr(_stringToSplit, oldPos, pos-oldPos));
        oldPos = pos+delLength;
    }
    while (pos <= strLength);

    return list;
}

public static utcDateTime convertStr2utcDateTime(str 100 datetimestr)
{
    utcDateTime dateOut = utcDateTimeNull();
    str 100 tempDateStr;
    System.String nDatetimestr = datetimestr;
    System.DateTime datetime;
    System.DateTime datetimeUTC;
    System.Globalization.CultureInfo daDK = new System.Globalization.CultureInfo('da-DK');
    System.Boolean b;
    boolean o;

    b = System.DateTime::TryParseExact(nDatetimestr, 'yyyy-MM-ddTHH:mm:ss.FFFzzz', daDK, System.Globalization.DateTimeStyles::AdjustToUniversal, byref datetime);
    o = b;
    if (!o)
    {
        b = System.DateTime::TryParseExact(nDatetimestr, 'yyyy-MM-ddTHH:mm:ss.FFzzz', daDK, System.Globalization.DateTimeStyles::AdjustToUniversal, byref datetime);
        o = b;
    }
    if (!o)
    {
        b = System.DateTime::TryParseExact(nDatetimestr, 'yyyy-MM-dd', daDK, System.Globalization.DateTimeStyles::None, byref datetime);
        o = b;
    }

    if (o == true)
    {
        try
        {
            //datetime = System.DateTime::ParseExact(datetimestr, "yyyy-MM-ddTHH:mm:ss.FFFzzz", daDK);
            datetimeUTC = datetime.ToUniversalTime();

            dateout = Global::clrSystemDateTime2UtcDateTime( datetimeUTC );

        }

        catch(Exception::Error)
        {
            dateOut = utcDateTimeNull();
        }

        catch(Exception::CLRError)
        {
            dateOut = utcDateTimeNull();
        }
    }
    if (dateOut == utcDateTimeNull())
    {
        tempDateStr = datetimestr;
        if (strlen(tempDateStr) >= 19)
        {
            tempDateStr = subStr(tempDateStr,1,19);
        }
        dateOut = DateTimeUtil::parse( tempDateStr);
    }

    return dateOut;
}

