/// <param name="inventDim">InventDim to correct</param>
/// <summary>
/// Will ensure the inventDim WMSLocationId, InventLocationId and InventSiteId is set
/// </summary>
/// <param name = "inventDim">InventDim to correct</param>
/// <param name = "_inventTransID"></param>
/// <returns>Returns true if changed</returns>
public static boolean EnsureInventDim(InventDim inventDim, InventTransId _inventTransID = '')
{
    boolean corrected = false;
    WMSLocation wmsLocation;
    InventTrans iTrs;
    InventTransOrigin iOrigin;

    #if.isAX6
    if (inventDim.wMSPalletId && !inventDim.wMSLocationId)
    {
        inventDim.wMSLocationId = WMSPallet::find(inventDim.wMSPalletId).wMSLocationId;

        corrected = true;
    }
    #endif
    TFMInventDimHelper::locationMismatch(inventDim, _inventTransID);
    if (inventDim.LicensePlateId && !inventDim.wMSLocationId)
    {
        if (!WHSLicensePlate::exist(inventDim.LicensePlateId))
        {
            WHSLicensePlate::createLicensePlate(inventDim.LicensePlateId);
        }
        inventDim.wMSLocationId = TFMInventDimHelper::WmsLocationIdFromLicensePlate(inventDim.LicensePlateId).wMSLocationId;
        if (_inventTransID && !inventDim.wMSLocationId)
        {
            select firstonly iTrs order by RecId desc where iTrs.inventDimId
                join iOrigin where iTrs.InventTransOrigin == iOrigin.recId && iOrigin.InventTransId == _inventTransID;

            inventDim.InventLocationId = inventDim.InventLocationId ? inventDim.InventLocationId : iTrs.inventLocationId();
            inventDim.wMSLocationId = InventLocation::find(inventDim.InventLocationId).WMSLocationIdDefaultReceipt;
        }
        corrected = true;
    }


    if (inventDim.wMSLocationId && !inventDim.InventLocationId)
    {
        if ((select count(RecId) from wmsLocation where wmsLocation.wMSLocationId == inventDim.wMSLocationId).RecId == 1)
        {
            wmsLocation.selectForUpdate(false);
            select firstOnly wmsLocation
                where wmsLocation.wMSLocationId == inventDim.wMSLocationId;

            if (wmsLocation)
            {
                inventDim.InventLocationId = wmsLocation.inventLocationId;
                corrected = true;
            }
        }
    }

    if (inventDim.InventLocationId && !inventDim.InventSiteId)
    {
        inventDim.InventSiteId = InventLocation::find(inventDim.InventLocationId).InventSiteId;
        corrected = true;
    }

    return corrected;
}

public static str getEnumValues(int _enumId)
{
    DictEnum        dictEnum;
    int             valueIndex;
    str             labelId;
    str             list;

    dictEnum    = new DictEnum(_enumId);

    if (dictEnum)
    {
        for (valueIndex = 0 ; valueIndex < dictEnum.values(); valueIndex++)
        {
            labelId = dictEnum.index2LabelId(valueIndex);
            list += SysLabel::labelId2String(labelId);
            // Do not add a value separator to the last element
            if (valueIndex < dictEnum.values()-1)
            {
                list += ';';
            }
        }
    }
    return list;
}

