    /// <summary>
    /// Converts a string to an ItemId - Looking for barcode for the Item. The invent Dim is set on the IDimLookup parameter if found.
    /// </summary>
    public static ItemId string2ItemID(str _value, InventDim _iDimLookup)
    {
        ItemId				itemId;
        Str                 inputItemId = _value;
        InventItemBarcode   inventItemBarcode;
        InventItemGTIN      inventItemGTIN;
        InventDim			iDim;

        // Determine if the provided value is a barcode or an item id
        inventItemBarcode = InventItemBarcode::findInputBarcode(inputItemId);
        if (inventItemBarcode)
        {
            itemId = inventItemBarcode.itemId;
            iDim = inventItemBarcode.inventDim();
        }
        else
        {
            inventItemGTIN = InventItemGTIN::findGTIN(inputItemId);
            if (inventItemGTIN)
            {
                itemId = inventItemGTIN.itemId;
                iDim = inventDim::find(inventItemGTIN.inventDimId);
            }
            else if (InventTable::exist(inputItemId))
            {
                itemId = InventTable::find(inputItemId).ItemId;
            }
        }

		if (iDim)
        {
            _iDimLookup.data(iDim);
        }
        return itemId;
    }

