}

/// <summary>
/// Provides a map that links a field group (concatenated by tableId and fieldGroupName) to a set of fields. The map is stored in memory cache, so it can be reused by different calls, and the field set only needs to be constructed once for each field group.
/// </summary>
/// <returns>A map of fields in field groups per table</returns>
protected static Map fieldGroupSetProvider()
{
    System.Runtime.Caching.ObjectCache memCache = System.Runtime.Caching.MemoryCache::Default;

    Map fieldGroupMap = memCache.Get(funcName());

    if(!fieldGroupMap)
    {
        fieldGroupMap = new Map (Types::String, Types::Class);
        memCache.Add(funcName(), fieldGroupMap, new System.Runtime.Caching.CacheItemPolicy());
    }
    return fieldGroupMap;
}

public static Set fieldGroupToSet(TableId _tableId, FieldGroupName _fieldGroupName)
{
    Set             retSet;
    DictTable       dTable;
    DictField       dField;
    DictFieldGroup  dFieldGroup;
    int             fieldId;
    int             counter;
    int             fieldCnt;
    str             key = strFmt('%1_%2', _tableId, _fieldGroupName);   
    Map             fieldGroupMap = TFMHelper::fieldGroupSetProvider();

    if (fieldGroupMap.exists(key))
    {
        return fieldGroupMap.lookup(key);
    }

    dTable = new DictTable(_tableId);
    retSet = new Set(Types::String);
    if (dTable)
    {
        for(counter = 1; counter <= dTable.fieldGroupCnt(); counter++)
        {
            if(_fieldGroupName == dTable.fieldGroup(counter))
            {
                dFieldGroup = new DictFieldGroup(_tableId, _fieldGroupName);
                if(dFieldGroup)
                {
                    for (fieldCnt=1; fieldCnt <= dFieldGroup.numberOfFields(); fieldCnt++)
                    {
                        fieldId = dFieldGroup.field(fieldCnt);
                        dField = new DictField(_tableId, FieldId);
                        if(dField)
                        {
                            retSet.add(dField.name());
                        }
                    }
                }
            }
        }
    }

    fieldGroupMap.insert(key, retSet);
    return retSet;
}

