public static str formatLineNum(LineNum _lineNum)
{
    int d = 0;

    while ((d < 10) && (_lineNum != str2num( num2str(_lineNum,1,d,1,0) ) ))
    {
        d++;
    }
    return num2str(_lineNum, 1, d, 1, 0);
}

public static str getConvertibleUnitList(InventTable _inventTable)
{
    UnitOfMeasureConversion conv;
    UnitOfMeasure uom;
    UnitOfMeasure uomSource;
    str chkList = ';';
    str unitList = '';

    uomSource = UnitOfMeasure::findBySymbol(_inventTable.inventUnitId() );
    unitList = unitList + _inventTable.inventUnitId();

    while select conv
        where conv.Product == _inventTable.Product
        join uom
        where uom.RecId == conv.FromUnitOfMeasure
    {
        if (strScan(chkList, ';'+uom.Symbol+';', 1, 1000) <= 0)
        {
            unitList = unitList + (unitList ? ';' : '') + uom.Symbol;
            chkList += uom.Symbol +';';
        }
    }

    while select conv
        where conv.Product == 0 // Standard conversion
           && conv.FromUnitOfMeasure == uomSource.RecId
        join uom
        where uom.RecId == conv.ToUnitOfMeasure
    {
        if (strScan(chkList, ';'+uom.Symbol+';', 1, 1000) <= 0)
        {
            unitList = unitList + (unitList ? ';' : '') + uom.Symbol;
            chkList += uom.Symbol + ';';
        }
    }

    return unitList;
}

