public static DocuRef findImageDocuRef(Common _record, DocuTypeId _typeID = '')
{
    DocuRef defaultDocuRef;
    select firstonly defaultDocuRef order by defaultDocuRef.CreatedDateTime desc
            where
                defaultDocuRef.RefTableId == _record.TableId
                && defaultDocuRef.RefRecId == _record.RecId
                && defaultDocuRef.RefCompanyId == _record.DataAreaId
                && (defaultDocuRef.TypeId == _typeID || !_typeID);


    return defaultDocuRef;
}

public static str makeDocurefHTML(Common _buffer)
{
    str                     html = '<html><body>';
    DocuRef                 docuRef;
    System.Drawing.Image    image;
    System.Drawing.Image    newImage;
    str                     base64str;
    boolean                 foundSome = false;

    html += '<table width="100%" cellspacing="0" cellpadding="2" border="0">';
    while select docuRef where docuRef.RefRecId == _buffer.RecId && docuRef.RefTableId == _buffer.tableId && docuRef.TypeId == TFMParameters::find().DocuTypeId
    {

        if (docuRef)
        {
            image = TFMHelper::getAttachmentAsImage(docuRef);
            if (image)
            {
                newImage = TFMImageHelper::scaleImage(image,250,250);

                base64str = TFMImageHelper::Image2Base64(newImage);

                html += '<tr><td colspan="2" align="center"><img src="data:image/png;base64,' + base64str + '" /></td></tr>';
                html += '<tr><td colspan="2" align="center">'+docuRef.Notes+'</td></tr>';
                foundSome = true;
            }
        }
    }
    html += '</table>';
    html += '</body></html>';

    return foundSome ? html : '';
}

/// <summary>
/// Finds the DocuRef record which carries the default image for the given record.
/// </summary>
/// <param name = "_record">Record with associated images.</param>
/// <returns>DocuRef record with default image</returns>
public static DocuRef findDefaultImageDocuRef(Common _record)
{
    #if.isAX6
    DocuRef defaultDocuRef;
    EcoResProductImage localEcoResProductImage;
    select firstonly defaultDocuRef
            where
                defaultDocuRef.RefTableId == _record.TableId
                && defaultDocuRef.RefRecId == _record.RecId
                && defaultDocuRef.RefCompanyId == _record.DataAreaId
            join localEcoResProductImage
            where
                defaultDocuRef.RecId == localEcoResProductImage.RefRecId
                && localEcoResProductImage.DefaultImage == NoYes::Yes;

    return defaultDocuRef;
    #endif
    #ifnot.isAX6
    return EcoResProductImage::findDefaultImageDocuRef(_record);
    #endif
}

/// <summary>
/// Retrieves a document attachment packed into container.
/// </summary>
/// <param name="_docuRef">A document reference that has an attached file.</param>
/// <returns>Container with the file contents.</returns>
/// <remarks>This method should not be used with File::sendFileToUser.  Instead use DocumentManagement::getAttachmentPublicUrl() and the Browser class.</remarks>
public static System.Drawing.Image getAttachmentAsImage(DocuRef _docuRef)
{
    #ifnot.isAX6
    try
    {
        return System.Drawing.Image::FromStream(DocumentManagement::getAttachmentStream(_docuRef));
    }
    catch 
    {
        return null;
    }
    #endif
    #if.isAX6

    DocuValue dValue;
    Binary      binary;
    EcoResProductImage localEcoResProductImage;

    BinData     binData = new BinData();
    System.IO.MemoryStream memoryStream;


    select firstonly dValue where dValue.RecId == _docuRef.ValueRecId;

    if (dValue && dValue.File != conNull())
    {
        return System.Drawing.Image::FromStream(Binary::constructFromContainer(localEcoResProductImage.MediumSize).getMemoryStream());
    }

    select firstonly localEcoResProductImage where _docuRef.RecId == localEcoResProductImage.RefRecId && localEcoResProductImage.DefaultImage == NoYes::Yes;
    return System.Drawing.Image::FromStream(Binary::constructFromContainer(localEcoResProductImage.MediumSize).getMemoryStream());

    #endif

}

public static str makeItemHTML(InventTable _inventTable)
{
    InventItemBarcode       inventItemBarcode;
    InventItemGTIN          inventItemGTIN;
    int                     tableLine;
    str                     html = '<html><body>';
    DocuRef                 docuRef;
    System.Drawing.Image    image;
    System.Drawing.Image    newImage;
    str                     base64str;
    html += '<b><u>' + _inventTable.productName(new xInfo().language()) + '</u></b><br/>';
    html += '<i>' + _inventTable.itemDescriptionOrName(new xInfo().language()) + '</i><br/>';
    html += '<table width="100%" cellspacing="0" cellpadding="2" border="0">';
    tableLine = 0;
    while select ItemBarCode, Qty, UnitId from inventItemBarcode
    where InventItemBarcode.itemId == _inventTable.itemId
        && inventItemBarcode.itemBarCode
        && inventItemBarcode.useForInput
    {
        tableLine++;
        html += '<tr '+((tableLine mod 2) == 0 ? 'bgcolor="#d8dcd8"':'')+'><td>'+inventItemBarcode.itemBarCode+'</td>'+
                '<td align="right">'+TFMHelper::formatItemQty(inventItemBarcode.qty, inventItemBarcode.UnitID)+'</td>'+
                '<td>'+inventItemBarcode.UnitID+'</td></tr>';
    }
    while select GlobalTradeItemNumber, UnitID from inventItemGTIN
    where inventItemGTIN.itemId == _inventTable.itemId
        && inventItemGTIN.GlobalTradeItemNumber
    {
        tableLine++;
        html += '<tr '+((tableLine mod 2) == 0 ? 'bgcolor="#d8dcd8"':'')+'><td>'+inventItemGTIN.GlobalTradeItemNumber+'</td>'+
                '<td align="right">'+TFMHelper::formatItemQty(1, inventItemGTIN.UnitID)+'</td>'+
                '<td>'+inventItemGTIN.UnitID+'</td></tr>';
    }

    docuRef = TFMHelper::findDefaultImageDocuRef(_inventTable);
    if (docuRef)
    { 
        image = TFMHelper::getAttachmentAsImage(docuRef);

        if(image)
        {
            newImage = TFMImageHelper::scaleImage(image,250,250);
            base64str = TFMImageHelper::Image2Base64(newImage);
        } 
        else
        {
            base64str = '';
        }

        html += '<tr><td colspan="2" align="center"><img src="data:image/png;base64,' + base64str + '" /></td></tr>';
    }
    html += '</table>';
    html += '</body></html>';

    return html;
}

    public static str makeHtmlFromCommon(Common _common)
    {
        str				html = '<html><body><h1>'+tableId2PName(_common.tableId) + ' (' +tableId2Name(_common.tableId) + ') '+"@TFM:fieldsanddata"+'</h1>';
        str				fieldsHtml ='<h2>'+"@TFM:PossibleFieldstouse"+'</h2><table><tr><th><h2><u>' + "@SYS25058" + '</u></h2></th><th><h2><u>'+ "@SYS34979" + '</u></h2></th><th><h2><u>'+ "@SYS7403"+ '</u></h2></th></tr>';
        str				methodsHtml ='<h2>'+"@TFM:PossibleDisplaymethodstouse" + '</h2><table><tr><th><h2><u>' + "@SYS34979" + '</u></h2></th><th><h2><u>'+ "@SYS7403" + '</u></h2></th></tr>';
        MapEnumerator   keyFields = TFMHelper::getPrimaryKeysFromTableName(tableId2Name(_common.TableID)).getEnumerator();
        DictField		dictField;
        SysDictTable	dt = new SysDictTable(_common.tableId);
        SetEnumerator	fgEnum = dt.fieldGroups().getEnumerator();
        DictFieldGroup	fg;
        int				i;
        MethodName		mName;
        SysDictMethod	method;
        SetEnumerator   sEnum = dt.methods(true,false,true).getEnumerator();
        Map				foundMethods = new Map(Types::String, Types::String);

        while (sEnum.moveNext())
        {            
            method = sEnum.current();
            mName = method.name();
            if (method.displayType() != DisplayFunctionType::Get)
            {
                continue;
            }
            if (method.parameterCnt() && method.parameterTypeName(1) == tableId2Name(_common.tableid))
            {
                foundMethods.insert(mName,strFmt('%1',dt.callObject(mName,_common,_common)));
                //methodsHtml += '<tr><td>'+ mName + '</td><td>'+strFmt('%1',dt.callObject(mName,_common,_common))+ '</td></tr>';
            }
            else if(method.parameterCnt() == 1 && method.parameterOptional(1) || !method.parameterCnt())
            {
                foundMethods.insert(mName,strFmt('%1',dt.callObject(mName,_common)));
                //methodsHtml += '<tr><td>'+ mName + '</td><td>'+strFmt('%1',dt.callObject(mName,_common))+ '</td></tr>';
            }
            if (foundMethods.exists(mName))
            {
				methodsHtml += '<tr><td>'+ mName + '</td><td>'+foundMethods.lookup(mName)+ '</td></tr>';
            }
        }

        methodsHtml += '</table>';


		if (dt.titleField1())
        {
            fieldsHtml += '<tr><td colspan="3"><b><i>' + "@TFM:TitleFields" + '</i></b></td></tr>';
            dictField = new DictField(_common.tableId,dt.titleField1());
            fieldsHtml += '<tr><td>' +dictField.label() + '</td><td>'+dictField.name() + '</td><td>'+strFmt('%1',_common.(dictField.id()))+ '</td></tr>';
			if (dt.titleField2())
            {
                dictField = new DictField(_common.tableId,dt.titleField2());
                fieldsHtml += '<tr><td>' +dictField.label() + '</td><td>'+dictField.name() + '</td><td>'+strFmt('%1',_common.(dictField.id()))+ '</td></tr>';
            }
        }

        fieldsHtml += '<tr><td colspan="3"><b><i>' + "@SYS87570" + '</i></b></td></tr>';
        while (keyFields.moveNext())
        {
            dictField = keyFields.currentValue();
            fieldsHtml += '<tr><td>' +dictField.label() + '</td><td>'+dictField.name() + '</td><td>'+strFmt('%1',_common.(dictField.id()))+ '</td></tr>';
        }

        while (fgEnum.moveNext())
        {
            fg = fgEnum.current();
            fieldsHtml += '<tr><td colspan="3"><b><i>' + strFmt("@SYS76766","@SYS76179",fg.label()) + '</i></b></td></tr>';
            for (i = 1; i <= fg.numberOfFields(); i++)
            {
                dictField = new DictField(_common.tableId,fg.field(i));
				if (dictField)
                {
                    fieldsHtml += '<tr><td>' +dictField.label() + '</td><td>'+dictField.name() + '</td><td>'+strFmt('%1',_common.(dictField.id()))+ '</td></tr>';
                }
                else if (foundMethods.exists(fg.methodName(fg.field(i))))
				{
					//Is display Method
                    mName = fg.methodName(fg.field(i));
                    fieldsHtml += '<tr><td>[' + "@SYS74330" + ']</td><td>'+ mName + '</td><td>'+foundMethods.lookup(mName)+ '</td></tr>';
				}
            }
        }
        fieldsHtml += '</table>';



        html += '<table><tr><td>'+fieldsHtml+'</td><td>' + methodsHtml + '</td></tr></table></body></html>';
        return html;
    }

public static str makeRelationsHtmlFromCommon(Common _common)
{
    str html = '<html><body>';
    str relationsHtml ='<h2>'+"@TFM:PossibleRelatedTablestouse" + '</h2><table><tr><th><h2><u>' + "@SYS25058" + '</u></h2></th><th><h2><u>'+ "@SYS34979" + '</u></h2></th></tr>';
    str relatedTableName;

    xRefTableRelation tblRelation;



    while select tblRelation where (tblRelation.TableName == tableId2Name(_common.tableId) || tblRelation.RelatedTableName == tableId2Name(_common.tableId))
    {
        relatedTableName = tblRelation.TableName == tableId2Name(_common.tableId) ? tblRelation.RelatedTableName : tblRelation.TableName;
        relationsHtml += '<tr><td>'+ tableId2PName(tableName2Id(relatedTableName)) + '</td><td>'+relatedTableName+ '</td></tr>';
    }

    relationsHtml += '</table>';

    html += relationsHtml + '</body></html>';
    return html;
}

public static str stripLastCharIfSlash(str _input)
{
    str output = _input;
    if(strEndsWith(output, '/'))
    {
        output = substr(output, 0, strLen(output)-1);
    }
    return output;
}

public static BinData resource2BinData(str _resStr)
{
    ResourceNode        node = SysResource::getResourceNode(_resStr);
    BinData             binData = new BinData();
    container           recourceNode;

    if(node)
    {
        recourceNode = SysResource::getResourceNodeData(node);
        binData.setData(recourceNode);
    }

    return binData;
}

public static str resource2str(str _resStr)
{
    //return TFMHelper::resource2BinData(_resStr).getStrData();
    str   ret;
    using(System.IO.Stream resourceStream = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetResourceContentStream(_resStr))
    {
        ret = new System.IO.StreamReader(resourceStream,System.Text.Encoding::Default).ReadToEnd();
    }
    return ret;
}

/// <summary>
/// Checks if any attachments exist for the record.
/// - duplicated from DocuRef::exists and added exists join to TFMParameters
/// </summary>
/// <param name = "refDataareaId">The data area to search.</param>
/// <param name = "refTableId">The table containing the record.</param>
/// <param name = "refRecId">The ID of the record.</param>
/// <returns>true if at least one attachment exists; otherwise, false.</returns>
public static boolean DocuRefexist(DataAreaId refDataareaId, TableId refTableId, RecId refRecId)
{
    DocuRef docuRef;
    TFMParameters tfmParameters;

    // Use a select list since DocuRef contains a memo field for notes, and customers
    // often add additional big fields. This will cause queries which select the whole
    // table buffer to take significant time, up to 100ms+. By selecting only the recid
    // this query will take ~2ms.
    select firstonly RecId from docuRef
                where docuRef.RefCompanyId  == refDataareaId &&
                      docuRef.RefTableId    == DocuRef::GetRootTableID(refTableId) &&
                      docuRef.RefRecId      == refRecId
            exists join tfmParameters
                where tfmParameters.DocuTypeId == docuRef.TypeId;

    return docuRef.RecId != 0;
}

public static str formatXml(str _xml)
{
    str ret;
    str tagContent;
    int indentLevel = 0;
    int pos = 1;
    int openTagPos;
    int closeTagPos;
    int xmlLength = strLen(_xml);
    boolean nodeClosed = false;
    str newLine = TFMConstants::newLine();
    str indent = TFMConstants::tab();

    while (pos <= xmlLength)
    {
        openTagPos = strScan(_xml, '<', pos, xmlLength-pos);
        if (openTagPos == 0)
        {
            ret += substr(_xml, pos, xmlLength - pos + 1);
            break;
        }
        else
        {
            ret += substr(_xml, pos, openTagPos - pos);
            closeTagPos = strScan(_xml, '>', openTagPos, xmlLength - pos + 1);
            if (closeTagPos == 0)
            {
                ret += substr(_xml, openTagPos, xmlLength - openTagPos + 1);
                break;
            }
            else
            {
                tagContent = substr(_xml, openTagPos + 1, closeTagPos - openTagPos - 1);
                if (subStr(tagContent,1,1) == '/')
                {
                    indentLevel--;
                    ret += (nodeClosed ? newLine + strRep(indent, indentLevel) : '') + '<' + tagContent + '>';
                    nodeClosed = true;
                }
                else 
                {
                    ret += (pos == 1 ? '' : newLine) + strRep(indent, indentLevel) + '<' + tagContent + '>';
                    if (subStr(tagContent,strLen(tagContent),1) != '/' && subStr(tagContent,1,1) != '?')
                    {
                        indentLevel++;
                    }
                    nodeClosed = false;
                }

                pos = closeTagPos + 1;
            }
        }
    }


    return ret;
}
